{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { Parser } from './parser.js'
import { formatJson, formatKeys } from './formatter.js'

const args = process.argv.slice(2)

if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
let input = ''
process.stdin.setEncoding('utf8')

process.stdin.on('data', (chunk) => {
  input += chunk
})

process.stdin.on('end', () => {
  try {
    const parser = new Parser(input)
    const document = parser.parse()

    if (mode === 'json') {
      const output = formatJson(document)
      process.stdout.write(output)
    } else {
      const output = formatKeys(document)
      process.stdout.write(output)
    }

    process.exit(0)
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }
})
"}

