{"file_path":"src/parser.js","content":"export class Parser {
  constructor(input) {
    this.input = input
    this.lines = input.split('\n')
    // Remove trailing empty line if input ends with newline
    if (this.input.endsWith('\n') && this.lines[this.lines.length - 1] === '') {
      this.lines.pop()
    }
    this.lineNum = 0
    this.document = {}
    this.currentTable = this.document
    this.currentTablePath = []
    this.definedTables = new Set()
    this.definedKeys = new Set()
    this.arrayOfTablesPath = null
  }

  parse() {
    for (this.lineNum = 0; this.lineNum < this.lines.length; this.lineNum++) {
      const line = this.lines[this.lineNum]
      const trimmed = line.trimStart()

      // Skip empty lines and comments
      if (!trimmed || trimmed[0] === '#' || trimmed[0] === ';') {
        continue
      }

      // Handle table headers
      if (line.trimStart()[0] === '[') {
        this.parseHeader(line)
      } else {
        // Parse key-value pair
        this.parseKeyValue(line)
      }
    }

    return this.document
  }

  parseHeader(line) {
    const trimmed = line.trimStart()
    let rest = trimmed.slice(1)
    let isArrayOfTables = false

    if (rest[0] === '[') {
      isArrayOfTables = true
      rest = rest.slice(1)
    }

    // Find closing bracket
    let closing = -1
    let inQuotes = false
    let quoteChar = null
    let escaped = false

    for (let i = 0; i < rest.length; i++) {
      const ch = rest[i]

      if (escaped) {
        escaped = false
        continue
      }

      if (ch === '\\' && (quoteChar === '"')) {
        escaped = true
        continue
      }

      if ((ch === '"' || ch === "'") && !inQuotes) {
        inQuotes = true
        quoteChar = ch
      } else if (ch === quoteChar && inQuotes) {
        inQuotes = false
        quoteChar = null
      } else if (ch === ']' && !inQuotes) {
        closing = i
        break
      }
    }

    if (closing === -1) {
      throw new Error(`line ${this.lineNum + 1}: unterminated table header`)
    }

    const nameStr = rest.slice(0, closing).trim()
    rest = rest.slice(closing + 1)

    if (isArrayOfTables) {
      if (rest[0] !== ']') {
        throw new Error(`line ${this.lineNum + 1}: unterminated table header`)
      }
      rest = rest.slice(1)
    }

    // Check for trailing text
    const afterBracket = rest.trim()
    if (afterBracket && !afterBracket.startsWith('#') && !afterBracket.startsWith(';')) {
      throw new Error(`line ${this.lineNum + 1}: trailing text after a table header`)
    }

    const path = this.parseDottedName(nameStr)

    if (isArrayOfTables) {
      this.createArrayOfTables(path)
    } else {
      this.createTable(path)
    }
  }

  createTable(path) {
    const pathStr = path.join('.')

    // Check if path already exists as something other than a table
    let current = this.document
    for (let i = 0; i < path.length; i++) {
      const key = path[i]
      if (!(key in current)) {
        current[key] = {}
      } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
        throw new Error(`line ${this.lineNum + 1}: ${pathStr} is not a table`)
      }
      current = current[key]
    }

    // Check if this exact table was already explicitly defined
    if (this.definedTables.has(pathStr)) {
      throw new Error(`line ${this.lineNum + 1}: table ${pathStr} is defined twice`)
    }

    this.definedTables.add(pathStr)
    this.currentTable = current
    this.currentTablePath = path
    this.arrayOfTablesPath = null
  }

  createArrayOfTables(path) {
    const pathStr = path.join('.')

    // Navigate to parent
    let current = this.document
    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i]
      if (!(key in current)) {
        current[key] = {}
      }
      if (typeof current[key] !== 'object') {
        throw new Error(`line ${this.lineNum + 1}: ${path.slice(0, i + 1).join('.')} is not a table`)
      }
      current = current[key]
    }

    const lastKey = path[path.length - 1]

    if (!(lastKey in current)) {
      current[lastKey] = []
    } else if (!Array.isArray(current[lastKey])) {
      throw new Error(`line ${this.lineNum + 1}: ${pathStr} is not an array of tables`)
    }

    const newTable = {}
    current[lastKey].push(newTable)
    this.currentTable = newTable
    this.currentTablePath = path
    this.arrayOfTablesPath = path
  }

  parseDottedName(str) {
    const parts = []
    let i = 0

    while (i < str.length) {
      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
        i++
      }

      if (i >= str.length) break

      // Parse name
      let name
      if (str[i] === '"' || str[i] === "'") {
        const result = this.parseString(str, i)
        name = result.value
        i = result.end
      } else {
        let start = i
        while (i < str.length && /[A-Za-z0-9_-]/.test(str[i])) {
          i++
        }
        if (i === start) {
          throw new Error(`line ${this.lineNum + 1}: expected a name`)
        }
        name = str.slice(start, i)
      }

      parts.push(name)

      // Skip whitespace
      while (i < str.length && (str[i] === ' ' || str[i] === '\t')) {
        i++
      }

      // Check for dot
      if (i < str.length && str[i] === '.') {
        i++
      } else if (i < str.length) {
        throw new Error(`line ${this.lineNum + 1}: expected a name`)
      }
    }

    if (parts.length === 0) {
      throw new Error(`line ${this.lineNum + 1}: expected a name`)
    }

    return parts
  }

  parseKeyValue(line) {
    let i = 0

    // Parse key (dotted name)
    let keyEndPos = -1
    let inQuotes = false
    let quoteChar = null
    let escaped = false

    for (let j = 0; j < line.length; j++) {
      const ch = line[j]

      if (escaped) {
        escaped = false
        continue
      }

      if (ch === '\\' && quoteChar === '"') {
        escaped = true
        continue
      }

      if ((ch === '"' || ch === "'") && !inQuotes) {
        inQuotes = true
        quoteChar = ch
      } else if (ch === quoteChar && inQuotes) {
        inQuotes = false
        quoteChar = null
      } else if (ch === '=' && !inQuotes) {
        keyEndPos = j
        break
      }
    }

    if (keyEndPos === -1) {
      throw new Error(`line ${this.lineNum + 1}: expected key = value`)
    }

    const keyStr = line.slice(0, keyEndPos).trim()
    let valueStr = line.slice(keyEndPos + 1)

    // Remove trailing comment
    valueStr = this.removeTrailingComment(valueStr)
    valueStr = valueStr.trim()

    if (!valueStr) {
      throw new Error(`line ${this.lineNum + 1}: expected a value`)
    }

    const keyPath = this.parseDottedName(keyStr)
    const value = this.parseValue(valueStr)

    // Set the value in the current table
    this.setValueInTable(keyPath, value)
  }

  removeTrailingComment(str) {
    let inQuotes = false
    let quoteChar = null
    let escaped = false

    for (let i = 0; i < str.length; i++) {
      const ch = str[i]

      if (escaped) {
        escaped = false
        continue
      }

      if (ch === '\\' && quoteChar === '"') {
        escaped = true
        continue
      }

      if ((ch === '"' || ch === "'") && !inQuotes) {
        inQuotes = true
        quoteChar = ch
      } else if (ch === quoteChar && inQuotes) {
        inQuotes = false
        quoteChar = null
      } else if ((ch === '#' || ch === ';') && !inQuotes) {
        return str.slice(0, i)
      }
    }

    return str
  }

  setValueInTable(keyPath, value) {
    let current = this.currentTable

    // Navigate through keys, creating intermediate tables as needed
    for (let i = 0; i < keyPath.length - 1; i++) {
      const key = keyPath[i]
      const fullPath = this.currentTablePath.concat(keyPath.slice(0, i + 1)).join('.')

      if (!(key in current)) {
        current[key] = {}
      } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
        throw new Error(`line ${this.lineNum + 1}: ${fullPath} is not a table`)
      }

      current = current[key]
    }

    const lastKey = keyPath[keyPath.length - 1]
    const fullPath = this.currentTablePath.concat(keyPath).join('.')

    if (lastKey in current) {
      throw new Error(`line ${this.lineNum + 1}: key ${fullPath} is defined twice`)
    }

    current[lastKey] = value
  }

  parseValue(str) {
    const trimmed = str.trim()

    if (trimmed === 'true') {
      return true
    } else if (trimmed === 'false') {
      return false
    } else if (trimmed.startsWith('"')) {
      return this.parseBasicString(trimmed)
    } else if (trimmed.startsWith("'")) {
      return this.parseLiteralString(trimmed)
    } else if (trimmed.startsWith('[')) {
      return this.parseArray(trimmed)
    } else if (trimmed.startsWith('{')) {
      return this.parseInlineTable(trimmed)
    } else {
      // Try to parse as number
      const num = this.parseNumber(trimmed)
      if (num !== null) {
        return num
      }
      throw new Error(`line ${this.lineNum + 1}: invalid value ${trimmed}`)
    }
  }

  parseNumber(str) {
    // Check for invalid # in the middle without whitespace
    const hashPos = str.indexOf('#')
    if (hashPos !== -1 && hashPos > 0 && str[hashPos - 1] !== ' ' && str[hashPos - 1] !== '\t') {
      return null
    }

    // Remove # and following text
    if (hashPos !== -1) {
      str = str.slice(0, hashPos).trim()
    }

    // Try integer
    let match = str.match(/^[+-]?\d(?:\d|_)*$/)
    if (match) {
      const numStr = str.replace(/_/g, '')
      return parseInt(numStr, 10)
    }

    // Try float
    match = str.match(/^[+-]?(?:\d(?:\d|_)*)?\.(?:\d(?:\d|_)*)?(?:[eE][+-]?\d(?:\d|_)*)?$/) ||
            str.match(/^[+-]?\d(?:\d|_)*\.(?:\d(?:\d|_)*)?(?:[eE][+-]?\d(?:\d|_)*)?$/) ||
            str.match(/^[+-]?\d(?:\d|_)*[eE][+-]?\d(?:\d|_)*$/)

    if (match) {
      const numStr = str.replace(/_/g, '')
      return parseFloat(numStr)
    }

    return null
  }

  parseBasicString(str) {
    if (!str.startsWith('"')) {
      throw new Error(`line ${this.lineNum + 1}: unterminated string`)
    }

    let result = ''
    let i = 1

    while (i < str.length) {
      const ch = str[i]

      if (ch === '\\') {
        if (i + 1 >= str.length) {
          throw new Error(`line ${this.lineNum + 1}: unterminated string`)
        }

        const nextCh = str[i + 1]
        switch (nextCh) {
          case '"':
            result += '"'
            i += 2
            break
          case '\\':
            result += '\\'
            i += 2
            break
          case 'n':
            result += '\n'
            i += 2
            break
          case 't':
            result += '\t'
            i += 2
            break
          case 'r':
            result += '\r'
            i += 2
            break
          case '0':
            result += '\0'
            i += 2
            break
          case 'u':
            if (i + 6 >= str.length) {
              throw new Error(`line ${this.lineNum + 1}: invalid escape \\u`)
            }
            const hex = str.slice(i + 2, i + 6)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw new Error(`line ${this.lineNum + 1}: invalid escape \\u`)
            }
            result += String.fromCharCode(parseInt(hex, 16))
            i += 6
            break
          default:
            throw new Error(`line ${this.lineNum + 1}: invalid escape \\${nextCh}`)
        }
      } else if (ch === '"') {
        return result
      } else {
        result += ch
        i++
      }
    }

    throw new Error(`line ${this.lineNum + 1}: unterminated string`)
  }

  parseLiteralString(str) {
    if (!str.startsWith("'")) {
      throw new Error(`line ${this.lineNum + 1}: unterminated string`)
    }

    let i = 1
    while (i < str.length) {
      if (str[i] === "'") {
        return str.slice(1, i)
      }
      i++
    }

    throw new Error(`line ${this.lineNum + 1}: unterminated string`)
  }

  parseString(str, startPos) {
    const quote = str[startPos]

    if (quote === '"') {
      let result = ''
      let i = startPos + 1

      while (i < str.length) {
        const ch = str[i]

        if (ch === '\\') {
          if (i + 1 >= str.length) {
            throw new Error(`line ${this.lineNum + 1}: unterminated string`)
          }

          const nextCh = str[i + 1]
          switch (nextCh) {
            case '"':
              result += '"'
              i += 2
              break
            case '\\':
              result += '\\'
              i += 2
              break
            case 'n':
              result += '\n'
              i += 2
              break
            case 't':
              result += '\t'
              i += 2
              break
            case 'r':
              result += '\r'
              i += 2
              break
            case '0':
              result += '\0'
              i += 2
              break
            case 'u':
              if (i + 6 >= str.length) {
                throw new Error(`line ${this.lineNum + 1}: invalid escape \\u`)
              }
              const hex = str.slice(i + 2, i + 6)
              if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
                throw new Error(`line ${this.lineNum + 1}: invalid escape \\u`)
              }
              result += String.fromCharCode(parseInt(hex, 16))
              i += 6
              break
            default:
              throw new Error(`line ${this.lineNum + 1}: invalid escape \\${nextCh}`)
          }
        } else if (ch === '"') {
          return { value: result, end: i + 1 }
        } else {
          result += ch
          i++
        }
      }

      throw new Error(`line ${this.lineNum + 1}: unterminated string`)
    } else if (quote === "'") {
      let i = startPos + 1
      while (i < str.length) {
        if (str[i] === "'") {
          return { value: str.slice(startPos + 1, i), end: i + 1 }
        }
        i++
      }
      throw new Error(`line ${this.lineNum + 1}: unterminated string`)
    }
  }

  parseArray(str) {
    if (!str.startsWith('[')) {
      throw new Error(`line ${this.lineNum + 1}: unterminated array`)
    }

    const result = []
    let i = 1
    let inQuotes = false
    let quoteChar = null
    let escaped = false
    let current = ''
    let depth = 0

    while (i < str.length) {
      const ch = str[i]

      if (escaped) {
        current += ch
        escaped = false
        i++
        continue
      }

      if (ch === '\\' && quoteChar === '"') {
        current += ch
        escaped = true
        i++
        continue
      }

      if ((ch === '"' || ch === "'") && !inQuotes) {
        inQuotes = true
        quoteChar = ch
        current += ch
      } else if (ch === quoteChar && inQuotes) {
        inQuotes = false
        quoteChar = null
        current += ch
      } else if (!inQuotes) {
        if (ch === '[' || ch === '{') {
          depth++
          current += ch
        } else if (ch === ']' || ch === '}') {
          if (depth === 0 && ch === ']') {
            // End of array
            const trimmed = current.trim()
            if (trimmed) {
              result.push(this.parseValue(trimmed))
            }

            // Check for trailing text
            const afterBracket = str.slice(i + 1).trim()
            if (afterBracket && !afterBracket.startsWith('#') && !afterBracket.startsWith(';')) {
              throw new Error(`line ${this.lineNum + 1}: trailing text after a value`)
            }

            return result
          }
          depth--
          current += ch
        } else if (ch === ',' && depth === 0) {
          const trimmed = current.trim()
          if (trimmed) {
            result.push(this.parseValue(trimmed))
          }
          current = ''
        } else if (ch === '#' || ch === ';') {
          // Comment in array
          const trimmed = current.trim()
          if (trimmed) {
            result.push(this.parseValue(trimmed))
          }

          // Skip to end of line or closing bracket
          i++
          while (i < str.length && str[i] !== ']') {
            i++
          }

          if (i >= str.length) {
            throw new Error(`line ${this.lineNum + 1}: unterminated array`)
          }

          // Don't increment i again, the loop will do it
          i--
          current = ''
        } else if (ch !== ' ' && ch !== '\t' && ch !== '\n' && ch !== '\r') {
          current += ch
        } else {
          current += ch
        }
      } else {
        current += ch
      }

      i++
    }

    throw new Error(`line ${this.lineNum + 1}: unterminated array`)
  }

  parseInlineTable(str) {
    if (!str.startsWith('{')) {
      throw new Error(`line ${this.lineNum + 1}: unterminated inline table`)
    }

    const result = {}
    let i = 1
    let inQuotes = false
    let quoteChar = null
    let escaped = false

    while (i < str.length) {
      const ch = str[i]

      if (escaped) {
        escaped = false
        i++
        continue
      }

      if (ch === '\\' && quoteChar === '"') {
        escaped = true
        i++
        continue
      }

      if ((ch === '"' || ch === "'") && !inQuotes) {
        inQuotes = true
        quoteChar = ch
      } else if (ch === quoteChar && inQuotes) {
        inQuotes = false
        quoteChar = null
      } else if (!inQuotes) {
        if (ch === '}') {
          // Check for trailing text
          const afterBrace = str.slice(i + 1).trim()
          if (afterBrace && !afterBrace.startsWith('#') && !afterBrace.startsWith(';')) {
            throw new Error(`line ${this.lineNum + 1}: trailing text after a value`)
          }
          return result
        } else if (ch === ',' || ch === ' ' || ch === '\t') {
          // Skip
        }
      }

      i++
    }

    throw new Error(`line ${this.lineNum + 1}: unterminated inline table`)
  }
}
