    if (keys.length === 0) {
      return '{}'
    }
    const items = keys.map(key => nextIndent + JSON.stringify(key) + ': ' + stringifyWithSortedKeys(value[key], depth + 1))
    return '{\n' + items.join(',\n') + '\n' + indent + '}'
  }

  return String(value)
